#!/usr/bin/env python3
"""Generate the spec tables that restate proto comment tags (plan row 1b).

Reads the comment tags (02e, "Comment tags"; parsed by proto_tags.py) from the
pinned buf's image (proto_image.py) and keeps six generated blocks in step:

  02k  RPCs by release, Watch topics by release   ([RELEASE])
  02d  scope per RPC, scope per Watch topic       ([SCOPE])
  02i  delivery class per event body              ([DELIVERY])
  02   capability map                             ([CAP], [DELIVERY], Dir)

A block sits between
  <!-- BEGIN GENERATED by scripts/gen-doc-tables.py from <proto>; do not edit by hand -->
  <!-- END GENERATED by scripts/gen-doc-tables.py from <proto> -->
and is never edited by hand. Dir in the capability map comes from structure:
an element reached from an AgentService request is A→H, from a response H→A,
from both "both" (ROOTS below is the only hand-kept list).

  gen-doc-tables.py --check   exit 1 if a tag is broken or a block is stale
  gen-doc-tables.py --write   rewrite the blocks (refuses on any problem)

Exit 0 clean; 1 problems (one line each); 2 the contract, the capability table
or the image could not be read. Fails closed: a missing marker is a problem.
"""
from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import proto_image  # noqa: E402
import proto_tags  # noqa: E402

NAME = "scripts/gen-doc-tables.py"
ROOTS = ("fleet.agent.v1.AgentService",)
A2H, H2A = "A→H", "H→A"
CAP_SOURCE = "api/fleet/*/v1/*.proto"


def begin(src):
    return "<!-- BEGIN GENERATED by %s from %s; do not edit by hand -->" % (NAME, src)


def end(src):
    return "<!-- END GENERATED by %s from %s -->" % (NAME, src)


def code(name):
    return "`%s`" % name


def cell(text):
    return text.replace("|", "\\|")


def runs(items):
    """Merge consecutive (name, key) pairs that share key: [([names], key)]."""
    out = []
    for name, key in items:
        if out and out[-1][1] == key:
            out[-1][0].append(name)
        else:
            out.append(([name], key))
    return out


def row_order(release_row):
    release, row = release_row
    number = re.match(r"[0-9]+", row)
    return (release != "v1", number is None, int(number.group()) if number else 0, row)


def release_table(tags, elements, label, name_of):
    groups, counts = {}, {}
    for element in elements:
        for tag in tags.tags(element, "RELEASE"):
            release, row = tag.value.split()
            groups.setdefault((release, row), []).append((name_of(element), tag.note))
        release = tags.one(element, "RELEASE").value.split()[0]
        counts[release] = counts.get(release, 0) + 1
    lines = ["| %s | Release | PR |" % (label[0].upper() + label[1:]), "|---|---|---|"]
    for key in sorted(groups, key=row_order):
        text = "; ".join(", ".join(map(code, names)) + (" (%s)" % note if note else "")
                         for names, note in runs(groups[key]))
        lines.append("| %s | %s | %s |" % (cell(text), key[0], key[1]))
    total = ", ".join("%d in %s" % (counts[r], r) for r in sorted(counts))
    return lines + ["", "%d %s: %s." % (len(elements), label, total)]


def scope_table(tags, elements, label, note_header, name_of):
    pairs = [(name_of(e), (tags.one(e, "SCOPE").value, tags.one(e, "SCOPE").note)) for e in elements]
    lines = ["| %s | Scope | %s |" % (label, note_header), "|---|---|---|"]
    for names, (scope, note) in runs(pairs):
        lines.append("| %s | %s | %s |" % (", ".join(map(code, names)), cell(code(scope)), cell(note)))
    return lines


def rpc_name(element):
    return element.name


def topic_name(element):
    return element.short or element.name


def render_rpc_releases(tags):
    return release_table(tags, tags.rpcs, "RPCs", rpc_name)


def render_topic_releases(tags):
    return release_table(tags, tags.topic_values, "topics", topic_name)


def render_rpc_scopes(tags):
    return scope_table(tags, tags.rpcs, "RPCs", "Note", rpc_name)


def render_topic_scopes(tags):
    return scope_table(tags, tags.topic_values, "Topics", "Row rule", topic_name)


def render_delivery(tags):
    lines = ["| Body | Class | `coalesce_key` | Why |", "|---|---|---|---|"]
    for arm in tags.arms:
        tag = tags.one(arm, "DELIVERY")
        cls, _, key = tag.value.partition(" ")
        lines.append("| %s | %s | %s | %s |" % (code(arm.name), cls, cell(code(key)) if key else "", cell(tag.note)))
    return lines


def reach(contract):
    """Full name -> set of directions, walking fields from the AgentService roots."""
    seen, stack = {}, []
    for root in ROOTS:
        if root not in contract.services:
            raise proto_tags.ContractError("the contract has no %s, the root of Dir" % root)
        for rpc in contract.services[root].rpcs.values():
            stack += [(contract.types[rpc.input], A2H), (contract.types[rpc.output], H2A)]
    while stack:
        target, direction = stack.pop()
        dirs = seen.setdefault(target.full_name, set())
        if direction in dirs:
            continue
        dirs.add(direction)
        for field in getattr(target, "fields", {}).values():
            if field.target is not None:
                stack.append((field.target, direction))
    return seen


def directions(element, seen):
    if element.kind == "rpc":
        return {A2H, H2A} if element.service.full_name in ROOTS else set()
    if element.kind == "field":
        return seen.get(element.full_name.rsplit(".", 1)[0], set())
    if element.kind == "enum value":
        return seen.get(element.enum.full_name, set())
    return seen.get(element.full_name, set())


def display(tags, element):
    contract = tags.contract
    if element.kind == "rpc":
        return element.service.name + "." + element.name
    if element.kind == "enum value":
        parent = proto_tags.local_name(contract, element.enum.full_name)
        return element.name if "." not in parent else parent + "." + element.name
    return proto_tags.local_name(contract, element.full_name)


def render_capmap(tags):
    seen = reach(tags.contract)
    tagged = {}
    for element in tags.contract.elements:
        for cid in tags.caps(element):
            tagged.setdefault(cid, []).append(element)
    lines = ["| ID | Element(s) | Dir | Delivery |", "|---|---|---|---|"]
    for cid, _ in tags.capabilities:
        elements = sorted(tagged.get(cid, []), key=lambda e: (e.file, e.order))
        if not elements:
            lines.append("| %s | local only | — | — |" % cid)
            continue
        dirs = set().union(*(directions(e, seen) for e in elements))
        where = "both" if len(dirs) == 2 else (dirs.pop() if dirs else "—")
        ids = {id(e) for e in elements}
        arms = [a for a in tags.arms if cid in tags.caps(a) or id(a.target) in ids]
        delivery = ", ".join("%s %s" % (code(a.name), tags.one(a, "DELIVERY").value.split()[0]) for a in arms)
        names = ", ".join(code(display(tags, e)) for e in elements)
        lines.append("| %s | %s | %s | %s |" % (cid, cell(names), where, delivery or "—"))
    return lines


BLOCKS = (  # (doc, which proto names the block, table name, renderer)
    ("docs/specs/02k-v1-surface-and-cli.md", "rpc", "RPCs by release", render_rpc_releases),
    ("docs/specs/02k-v1-surface-and-cli.md", "topic", "Watch topics by release", render_topic_releases),
    ("docs/specs/02d-hub-authz.md", "rpc", "scope per RPC", render_rpc_scopes),
    ("docs/specs/02d-hub-authz.md", "topic", "scope per Watch topic", render_topic_scopes),
    ("docs/specs/02i-delivery-and-sequencing.md", "event", "delivery class per event body", render_delivery),
    ("docs/specs/02-contracts.md", "cap", "capability map", render_capmap),
)


def source(tags, which):
    anchor = {"rpc": tags.service, "topic": tags.topics, "event": tags.event}.get(which)
    return "api/" + anchor.file if anchor else CAP_SOURCE


def apply(text, src, table, body):
    """(new text, problem or None) with one block's body replaced."""
    lines = text.split("\n")
    starts = [i for i, line in enumerate(lines) if line == begin(src)]
    if len(starts) != 1:
        return text, ("no BEGIN GENERATED marker for %s (from %s)" if not starts
                      else "more than one BEGIN GENERATED marker for %s (from %s)") % (table, src)
    stops = [i for i, line in enumerate(lines) if line == end(src) and i > starts[0]]
    if not stops:
        return text, "no END GENERATED marker for %s (from %s)" % (table, src)
    if lines[starts[0] + 1:stops[0]] == body:
        return text, None
    new = lines[:starts[0] + 1] + body + lines[stops[0]:]
    return "\n".join(new), "%s (from %s) is out of date; run %s --write" % (table, src, NAME)


def run(root, tags, write):
    problems, docs = [], {}
    for doc, which, table, render in BLOCKS:
        if doc not in docs:
            try:
                docs[doc] = [(root / doc).read_text(), False, set()]
            except OSError as err:
                problems.append("%s: cannot read it: %s" % (doc, err))
                docs[doc] = [None, False, set()]
        entry = docs[doc]
        if entry[0] is None:
            continue
        src = source(tags, which)
        entry[2].update((begin(src), end(src)))
        entry[0], problem = apply(entry[0], src, table, render(tags))
        if problem and "out of date" in problem:
            entry[1] = True
            if write:
                continue
        if problem:
            problems.append("%s: %s" % (doc, problem))
    for doc, (text, _, known) in docs.items():
        for n, line in enumerate((text or "").split("\n"), 1):
            if line.startswith(("<!-- BEGIN GENERATED by " + NAME, "<!-- END GENERATED by " + NAME)) and line not in known:
                problems.append("%s:%d: a generated-block marker this script does not know" % (doc, n))
    if write and not problems:
        for doc, (text, changed, _) in docs.items():
            if changed:
                (root / doc).write_text(text)
                print("gen-doc-tables: rewrote %s" % doc)
    return problems


def main(argv):
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--root", default=str(Path(__file__).resolve().parents[1]))
    parser.add_argument("--image", help="a prebuilt buf image (JSON); default $%s, else build" % proto_image.IMAGE_ENV)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true")
    mode.add_argument("--write", action="store_true")
    args = parser.parse_args(argv)
    root = Path(args.root).resolve()
    try:
        tags = proto_tags.Tags(proto_image.load(root, args.image), root)
        problems = tags.problems or run(root, tags, args.write)
    except (proto_image.ProtoImageError, proto_tags.ContractError) as err:
        print("gen-doc-tables: " + str(err), file=sys.stderr)
        return 2
    for line in problems:
        print(line)
    if problems:
        print("gen-doc-tables: %d problem(s); tag rules: docs/specs/02e-contract-rules.md, Comment tags"
              % len(problems), file=sys.stderr)
        return 1
    print("gen-doc-tables: %d generated blocks match the proto comment tags" % len(BLOCKS))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
